CREATE SCHEMA b;
CREATE TABLE b.entity(id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('assignment','attachment','building','campaign','capture','client','commit','deal','decision','decision_event','defect','deployment','doctrine_document','doctrine_section','engagement','event','f01_corporate_artifact','f01_document','format','incident','job_receipt','lead','loop','next_action','party','pillar','platform','property_negotiation','record_flag','record_source','relationship','repo','rule','run','siep_package','vendor','work_request')), UNIQUE(id,kind));
CREATE TABLE b.d_assignment(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'assignment' CHECK(kind='assignment'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_attachment(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'attachment' CHECK(kind='attachment'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_building(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'building' CHECK(kind='building'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_campaign(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'campaign' CHECK(kind='campaign'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_capture(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'capture' CHECK(kind='capture'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_client(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'client' CHECK(kind='client'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_commit(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'commit' CHECK(kind='commit'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_deal(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'deal' CHECK(kind='deal'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_decision(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'decision' CHECK(kind='decision'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_decision_event(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'decision_event' CHECK(kind='decision_event'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_defect(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'defect' CHECK(kind='defect'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_deployment(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'deployment' CHECK(kind='deployment'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_doctrine_document(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'doctrine_document' CHECK(kind='doctrine_document'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_doctrine_section(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'doctrine_section' CHECK(kind='doctrine_section'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_engagement(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'engagement' CHECK(kind='engagement'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_event(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'event' CHECK(kind='event'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_f01_corporate_artifact(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'f01_corporate_artifact' CHECK(kind='f01_corporate_artifact'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_f01_document(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'f01_document' CHECK(kind='f01_document'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_format(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'format' CHECK(kind='format'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_incident(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'incident' CHECK(kind='incident'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_job_receipt(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'job_receipt' CHECK(kind='job_receipt'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_lead(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'lead' CHECK(kind='lead'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_loop(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'loop' CHECK(kind='loop'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_next_action(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'next_action' CHECK(kind='next_action'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_party(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'party' CHECK(kind='party'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_pillar(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'pillar' CHECK(kind='pillar'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_platform(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'platform' CHECK(kind='platform'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_property_negotiation(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'property_negotiation' CHECK(kind='property_negotiation'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_record_flag(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'record_flag' CHECK(kind='record_flag'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_record_source(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'record_source' CHECK(kind='record_source'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_relationship(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'relationship' CHECK(kind='relationship'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_repo(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'repo' CHECK(kind='repo'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_rule(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'rule' CHECK(kind='rule'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_run(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'run' CHECK(kind='run'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_siep_package(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'siep_package' CHECK(kind='siep_package'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_vendor(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'vendor' CHECK(kind='vendor'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.d_work_request(id uuid PRIMARY KEY,payload text NOT NULL,kind text NOT NULL DEFAULT 'work_request' CHECK(kind='work_request'),FOREIGN KEY(id,kind) REFERENCES b.entity(id,kind));
CREATE TABLE b.edge(id uuid PRIMARY KEY,family text NOT NULL,src_kind text NOT NULL,src_id uuid NOT NULL,dst_kind text NOT NULL,dst_id uuid NOT NULL,relation text NOT NULL,CHECK((family='doctrine_link' AND src_kind='doctrine_section' AND dst_kind IN ('doctrine_document','doctrine_section','party','deal','decision','rule','loop','capture') AND relation IN ('citation','related','example','source')) OR (family='incident_link' AND src_kind='incident' AND dst_kind IN ('run','deployment','work_request','defect','decision') AND relation IN ('reference')) OR (family='siep_evidence_link' AND src_kind='siep_package' AND dst_kind IN ('job_receipt','decision_event') AND relation IN ('source','tests','migration','deploy','readback','live_readback','rollback','independent_review','joe_approval','joe_go_no_go','zero_unresolved_findings','zero_blockers','two_clean_audit_cycles','material_fix')) OR (family='f01_derivative_link' AND src_kind='f01_corporate_artifact' AND dst_kind IN ('party','lead','deal','rule','doctrine_section','loop','decision') AND relation IN ('reference')) OR (family='j102_document_link' AND src_kind='f01_document' AND dst_kind IN ('relationship','engagement','assignment','property_negotiation','deal') AND relation IN ('reference')) OR (family='j102_artifact_link' AND src_kind='f01_corporate_artifact' AND dst_kind IN ('relationship','engagement','assignment','property_negotiation','deal') AND relation IN ('reference')) OR (family='event' AND src_kind='event' AND dst_kind IN ('party','lead','deal','rule','doctrine_section','loop','decision') AND relation IN ('reference')) OR (family='record_source' AND src_kind='record_source' AND dst_kind IN ('party','lead','deal','rule','doctrine_section','loop','decision','client','building') AND relation IN ('reference')) OR (family='next_action' AND src_kind='next_action' AND dst_kind IN ('deal','client','lead','vendor') AND relation IN ('reference')) OR (family='record_flag' AND src_kind='record_flag' AND dst_kind IN ('lead','client','vendor','party','deal','campaign','platform','pillar','format','repo','commit') AND relation IN ('reference')) OR (family='attachment' AND src_kind='attachment' AND dst_kind IN ('party','lead','deal','rule','doctrine_section','loop','decision') AND relation IN ('reference'))),FOREIGN KEY(src_id,src_kind) REFERENCES b.entity(id,kind),FOREIGN KEY(dst_id,dst_kind) REFERENCES b.entity(id,kind),UNIQUE(family,src_kind,src_id,dst_kind,dst_id,relation));
CREATE INDEX ON b.edge(src_kind,src_id);
CREATE INDEX ON b.edge(dst_kind,dst_id);
CREATE VIEW b.relationships AS SELECT * FROM b.edge;
CREATE UNIQUE INDEX ON b.edge(src_id,dst_kind,dst_id) WHERE family='siep_evidence_link';
CREATE UNIQUE INDEX ON b.edge(dst_kind,dst_id) WHERE family='f01_derivative_link';
